ytick = {-6,-4,...,6},
minor xtick={-5,-4,...,7},
minor ytick={-5,-4,...,7},
%xticklabels={,,},
%yticklabels={,,},
xlabel = $x$,
ylabel = {$y$},
xlabel style={below right},
ylabel style={above left}
]

%Graphic:
\addplot [domain=-6:12,samples=200, color=deepskyblue, line width=1pt, dashed]{x+3} node[midway, sloped, above, xshift=-110pt, yshift=0pt] {\color{black}{$y=x+3$}};
% Shaded Region
\draw[draw=none, color=deepskyblue, fill=deepskyblue!40, fill opacity=0.5]  
	plot[domain=-150:15, samples=100] 
		(axis cs: {\x}, {\x+3}) 
			-- (current page.north east) 
			-- (current page.south east) 
			-- cycle;

\draw[color=deepskyblue] (axis cs:3.0,-2.0) node {$y <    x+3$};

\node[circle, draw=none, fill=orangepeel, inner sep=2pt] at (axis cs:0,1) {};

\end{axis}
\end{tikzpicture}
